using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class WeakPV14Checks {
 const string Pending="WeakPV14Checks";static int[] Holds={2,2,3,5,2,2,2,2,2,2};static int[] Sole={1500,1502,1506,1501,1502,1501,1502,1503,1500,1500};static TrainingFighter f;static TrainingOverlay hud;static ArmoredStaticPoseView view;static TrainingMove move;static List<string> rows;static HashSet<Sprite> seen;static int count,stage;static long start;static string report,bytes;static double deadline;static float x,y;static readonly FieldInfo Timer=typeof(TrainingFighter).GetField("timer",BindingFlags.Instance|BindingFlags.NonPublic);
 static WeakPV14Checks(){if(SessionState.GetBool(Pending,false))EditorApplication.update+=Tick;}static void C(bool ok,string text){if(!ok)throw new Exception(text);count++;rows.Add("PASS "+text);}
 public static void Run(){if(EditorApplication.isPlaying)throw new Exception("Fresh session required");EditorSceneManager.OpenScene(TrainingFlowSession.TrainingScene);SessionState.SetBool(Pending,true);EditorApplication.update-=Tick;EditorApplication.update+=Tick;EditorApplication.EnterPlaymode();}
 static void Setup(){rows=new List<string>();seen=new HashSet<Sprite>();var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"-weakReport");report=i<0?"Temp/weakv14.txt":args[i+1];deadline=EditorApplication.timeSinceStartup+120;hud=UnityEngine.Object.FindAnyObjectByType<TrainingOverlay>();f=hud.player;view=f.GetComponent<ArmoredStaticPoseView>();move=f.moveSet.Find(TrainingCommand.Light);bytes=File.ReadAllText(WeakPV14Install.Root+"/Data.asset");C(move.spriteSequence.frames.Length==10,"adopted10 source poses resolve into runtime");C(move.spriteSequence.frames.Select(v=>v.holdFrames).SequenceEqual(Holds),"24F provisional holds preserved on reload");C(move.startupFrames==7.2f&&move.activeFrames==4.8f&&move.recoveryFrames==13.2f,"original7.2/4.8/13.2 move phases unchanged");C(AssetDatabase.GetAssetPath(view.characterProfile.weakPunch).Contains("/LegacySprite/"),"old fallback image retained outside detection");var source=AssetDatabase.LoadAssetAtPath<TrainingMoveData>(WeakPV14Install.Root+"/Data.asset");var draft=UnityEngine.Object.Instantiate(source);try{SkillSpriteFolderSync.Sync(source,draft);C(draft.data.spriteSequence.frames.Select(v=>v.holdFrames).SequenceEqual(Holds),"resync retains imported hold values by GUID");}finally{UnityEngine.Object.DestroyImmediate(draft);}f.InputBuffer.Push(TrainingCommand.Light,f.LockKind);stage=0;}
 static void Frame(float frame){Timer.SetValue(f,frame/60);view.Present(f,"Attack",0);}
 static void Capture(string name){var cam=Camera.main;var target=cam.targetTexture;var active=RenderTexture.active;var rt=new RenderTexture(1280,720,24);var previousPosition=cam.transform.position;float size=cam.orthographicSize,aspect=cam.aspect;rt.Create();try{cam.transform.position=new Vector3(f.transform.position.x,1.2f,previousPosition.z);cam.orthographicSize=2;cam.aspect=16f/9;cam.targetTexture=rt;typeof(TrainingOverlay).GetMethod("LateUpdate",BindingFlags.Instance|BindingFlags.NonPublic)?.Invoke(hud,null);cam.Render();RenderTexture.active=rt;var image=new Texture2D(1280,720,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1280,720),0,0);image.Apply();File.WriteAllBytes(Path.ChangeExtension(report,null)+"-"+name+".png",image.EncodeToPNG());UnityEngine.Object.Destroy(image);}finally{cam.targetTexture=target;cam.orthographicSize=size;cam.aspect=aspect;cam.transform.position=previousPosition;RenderTexture.active=active;rt.Release();UnityEngine.Object.Destroy(rt);}}
 static void Tick(){try{if(!EditorApplication.isPlaying||Time.frameCount<5)return;if(rows==null){Setup();return;}if(EditorApplication.timeSinceStartup>deadline)throw new Exception("Weakv14 timeout");if(stage==0&&f.CurrentPhase==TrainingFighter.Phase.Attack){Time.timeScale=0;x=f.transform.position.x;y=f.transform.position.y;for(int direction=0;direction<2;direction++){f.opponent.GetComponent<TrainingMotor2D>().Teleport(new Vector2(f.transform.position.x+(direction==0?2:-2),.01f));f.RefreshTrainingFacing();int frame=0;for(int i=0;i<10;i++){Frame(frame+.1f);var sprite=move.spriteSequence.frames[i].sprite;C(view.image.sprite==sprite,"runtime pose "+(i+2)+" facing "+f.Facing);C(view.image.flipX==(f.Facing<0),"mirrored pose "+(i+2));C(Mathf.Abs(view.image.transform.localScale.x-view.CalibratedVisualScale)<.0001f&&Mathf.Abs(sprite.pixelsPerUnit-700)<.001f,"same body calibration "+(i+2));float foot=(1536-Sole[i]-sprite.pivot.y)/sprite.pixelsPerUnit*view.CalibratedVisualScale+view.image.transform.localPosition.y;C(Mathf.Abs(foot)<.0001f,"sole stays at body ground "+(i+2));frame+=Holds[i];}Frame(9);C(view.image.sprite.name.StartsWith("05-"),"full reach image occupies current active phase");Capture(direction==0?"right-active":"left-active");Frame(23);Capture(direction==0?"right-recovery":"left-recovery");}C(f.transform.position.x==x&&f.transform.position.y==y,"preview sampling never moves physical body");float artReach=(1001-move.spriteSequence.frames[3].sprite.pivot.x)/700*view.CalibratedVisualScale;float hitReach=move.center.z+move.halfSize.z;rows.Add("GEOMETRY fistApprox="+artReach+"m existingHitboxTip="+hitReach+"m gap="+(hitReach-artReach)+"m (unchanged collision)");Frame(0);start=f.InputBuffer.Frame;Time.timeScale=1;stage=1;}else if(stage==1){if(f.CurrentPhase==TrainingFighter.Phase.Attack){C(view.image.sprite!=null,"natural action sprite exists");seen.Add(view.image.sprite);}if(f.InputBuffer.Frame-start>36){C(f.CurrentPhase!=TrainingFighter.Phase.Attack,"normal action completes without duration extension");C(seen.Count>=3,"natural combat clock advances multiple adopted poses");C(File.ReadAllText(WeakPV14Install.Root+"/Data.asset")==bytes,"Play never writes authoring skill");C(f.GetComponent<ApprovedLocomotionTuning>().canonicalProfile==f.opponent.GetComponent<ApprovedLocomotionTuning>().canonicalProfile,"shared locomotion preserved");rows.Add("NATURAL distinct rendered poses="+seen.Count);Finish(0);}}}catch(Exception e){rows?.Add("FAIL "+e);Debug.LogException(e);Finish(1);}}
 static void Finish(int exit){SessionState.SetBool(Pending,false);EditorApplication.update-=Tick;Time.timeScale=1;rows?.Add(count+" PASS; exit="+exit+"; actual scene with scripted input/frame samples and camera renders, not physical input");if(rows!=null)File.WriteAllLines(report,rows);EditorApplication.Exit(exit);}
}
